-- 0014_global_countries: the platform is global.
--
-- Every ISO 3166-1 country becomes a row of `markets` (a market IS a
-- country), each with its ISO 4217 currency and the IANA time zone of its
-- capital. Any of them may be used by a lister; nothing is "planned" any
-- more. What the public is shown in country lists is decided at read time:
-- the countries that have published listings (GET /v1/countries?has_listings=true).
--
-- Written for a database that already holds data (migrations 0001-0013 have
-- run on staging, and the sample data is seeded there):
--
--   * The five existing countries (ZW, GB, AE, BW, ZA) keep their IDs, their
--     display order and every row that points at them. AE, BW and ZA go from
--     PLANNED to ACTIVE.
--   * Country rows are upserts by code. A row that already exists keeps its
--     ID; its name, currency and time zone are brought to the table in
--     internal/modules/markets/countries.go (a test keeps the two in step).
--   * Only columns are added to listings, directory_profiles and
--     onboarding_applications; no existing value is rewritten, except that an
--     onboarding application of a business gains its country (copied from the
--     market it already had).

-- ---------------------------------------------------------------------------
-- Countries. `enabled` is for the rare case a country must be switched off:
-- a disabled country is not listed and not accepted. `status` is kept for
-- older clients and no longer gates anything.
-- ---------------------------------------------------------------------------
ALTER TABLE markets ADD COLUMN enabled boolean NOT NULL DEFAULT true;


-- Any other row that was still PLANNED (there should be none).
UPDATE markets SET status = 'ACTIVE', updated_at = now() WHERE status = 'PLANNED';

-- ---------------------------------------------------------------------------
-- Free-text places. Regions, cities and suburbs stay reference rows, but
-- most countries have none yet. A listing or a profile there names its city
-- (and optionally its region) as plain text instead of a code: at most 80
-- characters, no markup. A row has a city code OR free text, never both.
-- Existing rows are untouched (the new columns are NULL for them).
-- ---------------------------------------------------------------------------
ALTER TABLE listings
    ADD COLUMN city_name   text CONSTRAINT listings_city_name_check
                           CHECK (char_length(city_name) BETWEEN 1 AND 80 AND city_name !~ '[<>[:cntrl:]]'),
    ADD COLUMN region_name text CONSTRAINT listings_region_name_check
                           CHECK (char_length(region_name) BETWEEN 1 AND 80 AND region_name !~ '[<>[:cntrl:]]'),
    ADD CONSTRAINT listings_free_text_place_check
        CHECK (city_code IS NULL OR city_code = '' OR (city_name IS NULL AND region_name IS NULL));

ALTER TABLE directory_profiles
    ADD COLUMN city_name   text CONSTRAINT directory_profiles_city_name_check
                           CHECK (char_length(city_name) BETWEEN 1 AND 80 AND city_name !~ '[<>[:cntrl:]]'),
    ADD COLUMN region_name text CONSTRAINT directory_profiles_region_name_check
                           CHECK (char_length(region_name) BETWEEN 1 AND 80 AND region_name !~ '[<>[:cntrl:]]'),
    ADD CONSTRAINT directory_profiles_free_text_place_check
        CHECK (city_code IS NULL OR city_code = '' OR (city_name IS NULL AND region_name IS NULL));

-- Profiles are filtered by their own country (market_id), which every
-- profile has had from the start.
CREATE INDEX directory_profiles_market_idx ON directory_profiles (market_id, kind) WHERE status = 'ACTIVE';

-- ---------------------------------------------------------------------------
-- Onboarding: a business says which country it is in, and its city as a code
-- (where the country has cities in the reference data) or as free text.
-- market_code stays what a market administrator is scoped by; for a business
-- it is the country. Existing business applications got their market from
-- their city, so that market is their country.
-- ---------------------------------------------------------------------------
ALTER TABLE onboarding_applications
    ADD COLUMN country_code text CONSTRAINT onboarding_applications_country_format CHECK (country_code ~ '^[A-Z]{2}$'),
    ADD COLUMN city_name    text CONSTRAINT onboarding_applications_city_name_check
                            CHECK (char_length(city_name) BETWEEN 1 AND 80 AND city_name !~ '[<>[:cntrl:]]');

UPDATE onboarding_applications
SET country_code = market_code
WHERE country_code IS NULL AND market_code ~ '^[A-Z]{2}$' AND agency_slug IS NULL;
